#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

// Create new node
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

// Insert at beginning
struct Node* insertBeginning(struct Node* head, int value) {
    struct Node* newNode = createNode(value);

    if (head == NULL) {
        newNode->next = newNode; // first node points to itself
        return newNode;
    }

    struct Node* temp = head;
    while (temp->next != head)
        temp = temp->next;

    temp->next = newNode;
    newNode->next = head;
    head = newNode;

    return head;
}

// Insert at end
struct Node* insertEnd(struct Node* head, int value) {
    struct Node* newNode = createNode(value);

    if (head == NULL) {
        newNode->next = newNode;
        return newNode;
    }

    struct Node* temp = head;
    while (temp->next != head)
        temp = temp->next;

    temp->next = newNode;
    newNode->next = head;

    return head;
}

// Display circular linked list
void display(struct Node* head) {
    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }

    struct Node* temp = head;
    printf("Circular List: ");
    do {
        printf("%d -> ", temp->data);
        temp = temp->next;
    } while (temp != head);
    printf("(head)\n");
}

// Sort the circular linked list (ascending)
void sortList(struct Node* head) {
    if (head == NULL || head->next == head)
        return; // empty or single node

    struct Node* current = head;
    struct Node* index;
    int temp;

    do {
        index = current->next;
        while (index != head) {
            if (current->data > index->data) {
                temp = current->data;
                current->data = index->data;
                index->data = temp;
            }
            index = index->next;
        }
        current = current->next;
    } while (current->next != head);
}

// --- Manual main ---
int main() {
    struct Node* head = NULL;

    // Insert few nodes manually
    head = insertEnd(head, 30);
    head = insertEnd(head, 10);
    head = insertEnd(head, 50);
    head = insertEnd(head, 20);
    head = insertEnd(head, 40);

    printf("\nBefore sorting:\n");
    display(head);

    sortList(head);

    printf("\nAfter sorting:\n");
    display(head);

    head = insertBeginning(head, 5);
    head = insertBeginning(head, 1);

    printf("\nAfter inserting at beginning:\n");
    display(head);

    sortList(head);

    printf("\nAfter sorting again:\n");
    display(head);

    return 0;
}
